const { error } = require('console');
const fs = require('fs-extra');
const path = require('path');

var _robloxPathDict;
var _options;

var luaProtos = {}


function tryParseProtosInOneFile(filePath, events) {
    filePath = filePath.replace(/\\/g, '/');
    var rbxPath = _robloxPathDict.getRbxPath(filePath)
    const fileContent = fs.readFileSync(filePath, 'utf8');

    // 提取各个block的内容
    const requestMatch = fileContent.match(/export type Request = {([^}]*)}/);
    const responseMatch = fileContent.match(/export type Response = {([^}]*)}/);
    const notifyMatch = fileContent.match(/export type Notify = {([^}]*)}/);
    const notifyAllMatch = fileContent.match(/export type NotifyAll = {([^}]*)}/);
    const notifySpecificMatch = fileContent.match(/export type NotifySpecific = {([^}]*)}/);

    luaProtos[rbxPath] = {
        FilePath: filePath,
        ProtoName: path.basename(filePath).replace(/\.proto\.lua$/, ''), // 去掉.proto.lua
        Request: requestMatch ? requestMatch[0].replace(/^export type Request =\s*/, '').trim() : undefined,
        Response: responseMatch ? responseMatch[0].replace(/^export type Response =\s*/, '').trim() : undefined,
        Notify: notifyMatch ? notifyMatch[0].replace(/^export type Notify =\s*/, '').trim() : undefined,
        NotifySpecific: notifySpecificMatch ? notifySpecificMatch[0].replace(/^export type NotifySpecific =\s*/, '').trim() : undefined,
        NotifyAll: notifyAllMatch ? notifyAllMatch[0].replace(/^export type NotifyAll =\s*/, '').trim() : undefined
    }
}



// 尝试生成路径, 如果有变更, 返回true
function tryGen(filePath, events) {

    var changed = false
    if (!fs.existsSync(filePath)) {
        return changed
    }

    // get file name
    const fileName = path.basename(filePath);

    if (fileName.endsWith(".proto.lua")) {
        tryParseProtosInOneFile(filePath, events);
        return true
    }
}

function findAndGenSubfolders(basePath, events) {
    if (_options.isIgnoreFolder(path.resolve(basePath))) return
    var changed = false

    if (!fs.existsSync(basePath)) {
        changed = true
        return false
    }

    // is dir
    if (fs.lstatSync(basePath).isDirectory()) {

        for (const item of fs.readdirSync(basePath, { withFileTypes: true })) {

            const fullPath = path.join(basePath, item.name);
            changed |= findAndGenSubfolders(fullPath, events);
        }
    } else {

        changed |= tryGen(basePath, events)
    }
    return changed
}

module.exports = {
    Init: function (options) {
        _options = options
        _robloxPathDict = options.robloxPathDict;
    },

    TryGen: function (paths) {
        var changed = false
        for (const basePath of paths) {
            changed |= findAndGenSubfolders(basePath);
        }
        return changed
    },
    TryGenOnUpdate: function (events) {
        var changed = false

        for (var key in events) {
            if (fs.existsSync(key)) {
                changed |= findAndGenSubfolders(key, events)
            } else {
                key = key.replace(/\\/g, '/');
                // foreach
                for (const [_, interfaceData] of Object.entries(luaProtos)) {
                    if (interfaceData.FilePath === key) {
                        delete luaProtos[_];
                        changed = true;
                        break;
                    }
                }

            }
        }

        return changed
    },

    GetLuaProtos: function () {
        return luaProtos
    }
}